#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum UnitFileState {
    UnitEnabled,
    UnitEnabledRuntime,
    UnitLinked,
    UnitMasked,
    UnitStatic,
    UnitDisabled,
    UnitIndirect,
    UnitGenerated,
    UnitTransient,
    UnitBad,
}

pub fn parse_unit_file_state(raw: String) -> Option<UnitFileState> {
    if (raw.clone() == "enabled".to_string()) {
        Some(UnitFileState::UnitEnabled)
    } else {
        if (raw.clone() == "enabled-runtime".to_string()) {
            Some(UnitFileState::UnitEnabledRuntime)
        } else {
            if (raw.clone() == "linked".to_string()) {
                Some(UnitFileState::UnitLinked)
            } else {
                if (raw.clone() == "masked".to_string()) {
                    Some(UnitFileState::UnitMasked)
                } else {
                    if (raw.clone() == "static".to_string()) {
                        Some(UnitFileState::UnitStatic)
                    } else {
                        if (raw.clone() == "disabled".to_string()) {
                            Some(UnitFileState::UnitDisabled)
                        } else {
                            if (raw.clone() == "indirect".to_string()) {
                                Some(UnitFileState::UnitIndirect)
                            } else {
                                if (raw.clone() == "generated".to_string()) {
                                    Some(UnitFileState::UnitGenerated)
                                } else {
                                    if (raw.clone() == "transient".to_string()) {
                                        Some(UnitFileState::UnitTransient)
                                    } else {
                                        if (raw.clone() == "bad".to_string()) {
                                            Some(UnitFileState::UnitBad)
                                        } else {
                                            std::option::Option::None
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

